const crypto = require('crypto');
const SEGREDO_JWT = "TROQUE-ESTA-CHAVE-JWT";
const TTL_ACESSO_SEGUNDOS = 30 * 60;

function paraBase64Url(bufOrStr) {
  const b64 = Buffer.isBuffer(bufOrStr) ? bufOrStr.toString('base64') : Buffer.from(bufOrStr).toString('base64');
  return b64.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function assinarJwt(payload, ttlSegundos) {
  const agora = Math.floor(Date.now() / 1000);
  const corpo = Object.assign({ iat: agora, exp: agora + ttlSegundos }, payload);
  const cabecalho = paraBase64Url(JSON.stringify({ alg: 'HS256', typ: 'JWT' }));
  const dados = paraBase64Url(JSON.stringify(corpo));
  const semAssinatura = cabecalho + '.' + dados;
  const assinatura = paraBase64Url(crypto.createHmac('sha256', SEGREDO_JWT).update(semAssinatura).digest());
  return semAssinatura + '.' + assinatura;
}

function verificarJwt(token) {
  if (typeof token !== 'string') return null;
  const partes = token.split('.');
  if (partes.length !== 3) return null;
  const [cabecalho, dados, assinatura] = partes;
  const esperada = paraBase64Url(crypto.createHmac('sha256', SEGREDO_JWT).update(cabecalho + '.' + dados).digest());
  const bufEsperado = Buffer.from(esperada);
  const bufRecebido = Buffer.from(assinatura);
  if (bufEsperado.length !== bufRecebido.length) return null;
  if (!crypto.timingSafeEqual(bufEsperado, bufRecebido)) return null;
  let payload;
  try {
    payload = JSON.parse(Buffer.from(dados.replace(/-/g, '+').replace(/_/g, '/'), 'base64').toString('utf8'));
  } catch (e) {
    return null;
  }
  if (!payload.exp || payload.exp < Math.floor(Date.now() / 1000)) return null;
  return payload;
}

function hashSenha(senha) {
  const salt = crypto.randomBytes(16).toString('hex');
  const derivado = crypto.scryptSync(senha, salt, 64).toString('hex');
  return salt + ':' + derivado;
}

function verificaSenha(senha, hashGuardado) {
  if (typeof hashGuardado !== 'string' || hashGuardado.indexOf(':') === -1) return false;
  const [salt, derivadoGuardado] = hashGuardado.split(':');
  const derivado = crypto.scryptSync(senha, salt, 64).toString('hex');
  const bufA = Buffer.from(derivado, 'hex');
  const bufB = Buffer.from(derivadoGuardado, 'hex');
  if (bufA.length !== bufB.length) return false;
  return crypto.timingSafeEqual(bufA, bufB);
}

const entrada = $input.first().json;
const operacao = entrada.operacao;

if (operacao === 'emitir') {
  const tokenAcesso = assinarJwt({ sub: String(entrada.usuarioId || ''), papel: entrada.papel || 'Usuario' }, TTL_ACESSO_SEGUNDOS);
  return [{ json: { tokenAcesso, expiraEmSegundos: TTL_ACESSO_SEGUNDOS } }];
}

if (operacao === 'verificar') {
  const payload = verificarJwt(entrada.tokenAcesso);
  if (!payload) {
    return [{ json: { valido: false } }];
  }
  return [{ json: { valido: true, usuarioId: payload.sub, papel: payload.papel } }];
}

if (operacao === 'hash_senha') {
  return [{ json: { hash: hashSenha(String(entrada.senha || '')) } }];
}

if (operacao === 'verifica_senha') {
  return [{ json: { valido: verificaSenha(String(entrada.senha || ''), String(entrada.hash || '')) } }];
}

return [{ json: { valido: false, erro: 'operacao desconhecida' } }];
